#!/usr/bin/env node
/**
 * Sync Pionier service-worker SHELL + CACHE_VERSION with index.html and
 * pionier-app.js version stamps.
 *
 * Usage:
 *   node scripts/sync-handpan-cache.mjs          # write sw.js + VERSION.txt
 *   node scripts/sync-handpan-cache.mjs --check  # exit 1 if out of sync
 *
 * Single source of truth for the cache generation:
 *   handpan-app/APP_VERSION  (integer, e.g. 104 → CACHE_VERSION pionier-v104)
 *
 * Per-asset ?v= stamps stay on each file reference in HTML / dynamic imports.
 * This script only ensures the SW precache list matches those stamps.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const appDir = path.join(root, 'handpan-app');
const checkOnly = process.argv.includes('--check');

const APP_VERSION_PATH = path.join(appDir, 'APP_VERSION');
const INDEX_PATH = path.join(appDir, 'index.html');
const APP_JS_PATH = path.join(appDir, 'pionier-app.js');
const CORE_JS_PATH = path.join(appDir, 'pionier-core.js');
const SW_PATH = path.join(appDir, 'sw.js');
const VERSION_TXT_PATH = path.join(appDir, 'VERSION.txt');

/** Always precache these even when they lack ?v= (offline core). */
const EXTRA_SHELL = [
  './',
  './index.html',
  './manifest.webmanifest',
  './icon.svg',
  './registerSW.js',
  './js/instrument.js',
  './js/gesture.js',
  './js/fx.js',
  './js/note-sample-bank.js',
  './js/loop-core.js',
  './js/app-state.js?v=1',
  './js/audio-core.js?v=2',
  './js/pionier-surface.js?v=146',
  './js/instruments/handpan-scales.js?v=6',
  './js/pad-layout.js?v=2',
  './og-pionier-synth.svg',
];

function read(file) {
  if (!fs.existsSync(file)) {
    console.error('Missing file:', path.relative(root, file));
    process.exit(1);
  }
  return fs.readFileSync(file, 'utf8');
}

function extractVersionedRefs(source) {
  const found = new Set();
  const re = /(?:href|src)=["'](\.\/[^"']+\?v=\d+)["']/g;
  let m;
  while ((m = re.exec(source))) found.add(m[1]);
  return found;
}

function extractDynamicImports(source) {
  const found = new Set();
  const patterns = [
    /new URL\(\s*['"](\.\/[^'"]+)['"]/g,
    /import\(\s*['"](\.\/[^'"]+)['"]/g,
    /from\s+['"](\.\/[^'"]+)['"]/g,
  ];
  for (const re of patterns) {
    let m;
    while ((m = re.exec(source))) {
      const p = m[1];
      if (p.endsWith('.js') || p.endsWith('.css') || p.includes('?v=')) {
        found.add(p.startsWith('./') ? p : `./${p}`);
      }
    }
  }
  return found;
}

function normalizeShellEntry(entry) {
  let e = entry.trim();
  if (!e.startsWith('./') && e !== './') e = `./${e.replace(/^\//, '')}`;
  return e;
}

function buildShell(indexHtml, appJs, coreJs) {
  const shell = new Set();
  for (const e of EXTRA_SHELL) shell.add(normalizeShellEntry(e));
  for (const e of extractVersionedRefs(indexHtml)) shell.add(normalizeShellEntry(e));
  for (const e of extractDynamicImports(appJs)) shell.add(normalizeShellEntry(e));
  if (coreJs) {
    for (const e of extractDynamicImports(coreJs)) shell.add(normalizeShellEntry(e));
  }
  const priority = ['./', './index.html', './manifest.webmanifest', './icon.svg'];
  const rest = [...shell].filter((e) => !priority.includes(e)).sort();
  return [...priority.filter((e) => shell.has(e)), ...rest];
}

function readAppVersion() {
  const raw = read(APP_VERSION_PATH).trim();
  const n = Number.parseInt(raw, 10);
  if (!Number.isFinite(n) || n < 1) {
    console.error('handpan-app/APP_VERSION must be a positive integer, got:', raw);
    process.exit(1);
  }
  return n;
}

function renderSw(cacheVersion, shell) {
  const shellLiteral = shell.map((e) => `  '${e}',`).join('\n');
  return `/**\n * Pionier service worker\n * CACHE_VERSION and SHELL query stamps MUST match index.html / pionier-app.js.\n * Generated by scripts/sync-handpan-cache.mjs \u2014 do not hand-edit SHELL.\n * Bump handpan-app/APP_VERSION then run: npm run sync:handpan\n *\n * Strategy:\n *  - HTML / navigations: network-first (fallback to cached index offline)\n *  - Versioned shell assets (?v=): network-first when online, cache fallback\n *  - Other same-origin GET: cache-first, then network\n *  - On activate: drop all caches except current CACHE_VERSION\n * Offline readiness: shell + core modules must be listed in SHELL and pre-cached on install.\n */\nconst CACHE_VERSION = '${cacheVersion}';\n\nconst SHELL = [\n${shellLiteral}\n];\n\nself.addEventListener('install', (event) => {\n  event.waitUntil((async () => {\n    const cache = await caches.open(CACHE_VERSION);\n    await Promise.all(SHELL.map(async (url) => {\n      try {\n        const res = await fetch(url, { cache: 'no-cache' });\n        if (res && res.ok) await cache.put(url, res);\n      } catch (_) {}\n    }));\n    await self.skipWaiting();\n  })());\n});\n\nself.addEventListener('activate', (event) => {\n  event.waitUntil((async () => {\n    const keys = await caches.keys();\n    await Promise.all(keys.filter((k) => k !== CACHE_VERSION).map((k) => caches.delete(k)));\n    await self.clients.claim();\n  })());\n});\n\nself.addEventListener('message', (event) => {\n  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();\n});\n\nfunction isDocumentRequest(req, url) {\n  if (req.mode === 'navigate') return true;\n  if (req.destination === 'document') return true;\n  const path = url.pathname;\n  return path.endsWith('.html') || path.endsWith('/') || path.endsWith('/handpan-app');\n}\n\nfunction isVersionedAsset(url) {\n  return url.search.includes('v=');\n}\n\nself.addEventListener('fetch', (event) => {\n  const req = event.request;\n  if (req.method !== 'GET') return;\n  const url = new URL(req.url);\n  if (url.origin !== self.location.origin) return;\n\n  if (isDocumentRequest(req, url)) {\n    event.respondWith(\n      fetch(req)\n        .then((res) => {\n          if (res && res.ok) {\n            const copy = res.clone();\n            caches.open(CACHE_VERSION).then((c) => c.put(req, copy)).catch(() => {});\n          }\n          return res;\n        })\n        .catch(() => caches.match(req).then((r) => r || caches.match('./index.html')))\n    );\n    return;\n  }\n\n  if (isVersionedAsset(url) && (url.pathname.endsWith('.js') || url.pathname.endsWith('.css'))) {\n    event.respondWith(\n      fetch(req)\n        .then((res) => {\n          if (res && res.ok) {\n            const copy = res.clone();\n            caches.open(CACHE_VERSION).then((c) => c.put(req, copy)).catch(() => {});\n          }\n          return res;\n        })\n        .catch(() => caches.match(req))\n    );\n    return;\n  }\n\n  event.respondWith(\n    caches.match(req).then((cached) => {\n      if (cached) return cached;\n      return fetch(req).then((res) => {\n        if (res && res.status === 200 && res.type !== 'opaque') {\n          const copy = res.clone();\n          caches.open(CACHE_VERSION).then((c) => c.put(req, copy)).catch(() => {});\n        }\n        return res;\n      });\n    })\n  );\n});\n`;
}

function extractCacheVersion(swSource) {
  const m = swSource.match(/const CACHE_VERSION\s*=\s*['"]([^'"]+)['"]/);
  return m ? m[1] : null;
}

function extractShell(swSource) {
  const m = swSource.match(/const SHELL\s*=\s*\[([\s\S]*?)\];/);
  if (!m) return null;
  const entries = [];
  const re = /['"]([^'"]+)['"]/g;
  let x;
  while ((x = re.exec(m[1]))) entries.push(x[1]);
  return entries;
}

function main() {
  const versionNum = readAppVersion();
  const cacheVersion = `pionier-v${versionNum}`;
  const indexHtml = read(INDEX_PATH);
  const appJs = read(APP_JS_PATH);
  const coreJs = fs.existsSync(CORE_JS_PATH) ? read(CORE_JS_PATH) : '';
  const shell = buildShell(indexHtml, appJs, coreJs);
  const nextSw = renderSw(cacheVersion, shell);

  if (checkOnly) {
    const current = read(SW_PATH);
    const curVer = extractCacheVersion(current);
    const curShell = extractShell(current);
    let ok = true;
    if (curVer !== cacheVersion) {
      console.error(`CACHE_VERSION mismatch: sw has ${curVer}, expected ${cacheVersion}`);
      ok = false;
    }
    const a = JSON.stringify(curShell);
    const b = JSON.stringify(shell);
    if (a !== b) {
      console.error('SHELL list mismatch between sw.js and index/app imports.');
      const curSet = new Set(curShell || []);
      const nextSet = new Set(shell);
      for (const e of shell) if (!curSet.has(e)) console.error('  missing in sw:', e);
      for (const e of curShell || []) if (!nextSet.has(e)) console.error('  extra in sw:', e);
      ok = false;
    }
    if (!ok) {
      console.error('\nRun: npm run sync:handpan');
      process.exit(1);
    }
    console.log(`OK \u00b7 ${cacheVersion} \u00b7 ${shell.length} shell entries`);
    return;
  }

  fs.writeFileSync(SW_PATH, nextSw);
  const today = new Date().toISOString().slice(0, 10);
  const versionTxt = [
    cacheVersion,
    today,
    `shell: ${shell.length} entries (synced from index.html + pionier-app.js)`,
    'run: npm run sync:handpan after changing ?v= stamps or APP_VERSION',
    '',
  ].join('\n');
  fs.writeFileSync(VERSION_TXT_PATH, versionTxt);

  console.log(`Wrote ${path.relative(root, SW_PATH)}`);
  console.log(`Wrote ${path.relative(root, VERSION_TXT_PATH)}`);
  console.log(`CACHE_VERSION=${cacheVersion}`);
  console.log(`SHELL entries: ${shell.length}`);
  for (const e of shell) console.log(' ', e);
}

main();
